import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <climits>
constexpr int BM = 128;
constexpr int BN = 64;
constexpr int BK = 32;
constexpr int BLOCK_THREADS = 256;
constexpr int TM = 8;
constexpr int TN = 4;
__device__ __forceinline__ void decode_k(
    int k, int KH, int KW, int& c, int& kh, int& kw)
{
    const int khw = KH * KW;
    c = k / khw;
    const int rem = k - c * khw;
    kh = rem / KW;
    kw = rem - kh * KW;
}
__device__ __forceinline__ void decode_m(
    int m, int OH, int OW, int& n, int& oh, int& ow)
{
    const int hw = OH * OW;
    n = m / hw;
    const int rem = m - n * hw;
    oh = rem / OW;
    ow = rem - oh * OW;
}
__global__ void conv2d_implicit_gemm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int OC, int KH, int KW,
    int OH, int OW,
    int sh, int sw, int ph, int pw, int dh, int dw,
    int M, int K)
{
    __shared__ float As[BK][BM];
    __shared__ float Bs[BK][BN];
    const int tid = threadIdx.x;
    const int m0 = blockIdx.x * BM;
    const int n0 = blockIdx.y * BN;
    const int tx = tid % (BN / TN);
    const int ty = tid / (BN / TN);
    const int m_base = ty * TM;
    const int n_base = tx * TN;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    for (int k0 = 0; k0 < K; k0 += BK) {
        for (int idx = tid; idx < BK * BM; idx += BLOCK_THREADS) {
            const int k_local = idx / BM;
            const int m_local = idx - k_local * BM;
            const int gk = k0 + k_local;
            const int gm = m0 + m_local;
            float v = 0.0f;
            if (gk < K && gm < M) {
                int c, kh, kw, n, oh, ow;
                decode_k(gk, KH, KW, c, kh, kw);
                decode_m(gm, OH, OW, n, oh, ow);
                const int ih = oh * sh - ph + kh * dh;
                const int iw = ow * sw - pw + kw * dw;
                if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                    v = input[((n * C + c) * H + ih) * W + iw];
                }
            }
            As[k_local][m_local] = v;
        }
        for (int idx = tid; idx < BK * BN; idx += BLOCK_THREADS) {
            const int oc_local = idx / BK;
            const int k_local = idx - oc_local * BK;
            const int gk = k0 + k_local;
            const int oc = n0 + oc_local;
            float v = 0.0f;
            if (gk < K && oc < OC) {
                v = weight[(int)((long long)oc * K + gk)];
            }
            Bs[k_local][oc_local] = v;
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_frag[TM];
            float b_frag[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a_frag[i] = As[kk][m_base + i];
            }
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b_frag[j] = Bs[kk][n_base + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int gm = m0 + m_base + i;
        if (gm >= M) continue;
        int n, oh, ow;
        decode_m(gm, OH, OW, n, oh, ow);
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int oc = n0 + n_base + j;
            if (oc < OC) {
                float v = acc[i][j];
                if (bias != nullptr) v += bias[oc];
                output[((n * OC + oc) * OH + oh) * OW + ow] = v;
            }
        }
    }
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    const int N = (int)input.size(0);
    const int C = (int)input.size(1);
    const int H = (int)input.size(2);
    const int W = (int)input.size(3);
    const int OC = (int)weight.size(0);
    const int KH = (int)weight.size(2);
    const int KW = (int)weight.size(3);
    TORCH_CHECK(weight.size(1) == C, "weight in_channels mismatch");
    const int sh = (int)stride_h;
    const int sw = (int)stride_w;
    const int ph = (int)pad_h;
    const int pw = (int)pad_w;
    const int dh = (int)dil_h;
    const int dw = (int)dil_w;
    const int eff_kh = (KH - 1) * dh + 1;
    const int eff_kw = (KW - 1) * dw + 1;
    const int OH = (H + 2 * ph - eff_kh) / sh + 1;
    const int OW = (W + 2 * pw - eff_kw) / sw + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");
    auto output = torch::empty({N, OC, OH, OW}, input.options());
    TORCH_CHECK(input.numel() < INT32_MAX && output.numel() < INT32_MAX, "tensor too large");
    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias->numel() == OC, "bias size mismatch");
        bias_ptr = bias->data_ptr<float>();
    }
    const int M = N * OH * OW;
    const int K = C * KH * KW;
    TORCH_CHECK(M > 0 && K > 0, "invalid reduction size");
    dim3 block(BLOCK_THREADS);
    dim3 grid((M + BM - 1) / BM, (OC + BN - 1) / BN);
    auto stream = at::cuda::getCurrentCUDAStream();
    conv2d_implicit_gemm_kernel<<<grid, block, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        OC, KH, KW,
        OH, OW,
        sh, sw, ph, pw, dh, dw,
        M, K);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

_conv_mod = load_inline(
    name="custom_conv2d_tiled",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1,
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = tuple(kernel_size)
        self.stride = int(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)

        kh, kw = self.kernel_size
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv_mod.conv2d_forward(
            x,
            self.weight,
            self.bias,
            self.stride,
            self.stride,
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
        )

